public class Driver { interface Switchable{void on();void off();boolean isOn();default void toggle(){if(isOn())off();else on();}}record Device(String name,boolean state)implements Switchable{public void on(){System.out.println(name+" turned ON");}public void off(){System.out.println(name+" turned OFF");}public boolean isOn(){return state;}}@FunctionalInterface interface Condition{boolean canSwitch(Switchable d,int hour);}public static void main(String[]a){Switchable fan=new Device("Fan",false),light=new Device("Light",false);fan.toggle();light.toggle();Condition daytime=(d,h)->h>=6&&h<=22,evening=(d,h)->h>=18;System.out.println("Can switch light at 20h (Anon): "+daytime.canSwitch(light,20));System.out.println("Can switch light at 10h (Lambda): "+evening.canSwitch(light,10));}}
